
.rules-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.rule-item {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  background: rgba(43, 29, 14, 0.2);
  border: 1px solid rgba(165, 113, 58, 0.2);
  border-radius: 0.4rem;
  padding: 0.5rem;
}

.rule-input {
  flex: 1;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(165, 113, 58, 0.3);
  border-radius: 0.25rem;
  padding: 0.4rem;
  font-size: 0.8rem;
  color: var(--text-primary, #f0e6d3);
  font-family: inherit;
  resize: vertical;
  min-height: 2.5rem;

  &:focus {
    outline: none;
    border-color: rgba(212, 177, 106, 0.8);
  }

  &::placeholder {
    color: rgba(184, 169, 143, 0.5);
  }
}

.delete-icon {
  color: rgba(255, 100, 100, 0.7);
  cursor: pointer;
  margin-top: 0.3rem;
  font-size: 0.8rem;
  transition: color 0.2s;

  &:hover {
    color: rgba(255, 80, 80, 1);
  }
}

.add-rule-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.5rem;
  border: 1px dashed rgba(165, 113, 58, 0.4);
  border-radius: 0.4rem;
  background: rgba(43, 29, 14, 0.1);
  color: var(--text-secondary, #b8a98f);
  font-size: 0.8rem;
  cursor: pointer;
  transition: all 0.2s;

  &:hover {
    background: rgba(43, 29, 14, 0.3);
    border-color: rgba(165, 113, 58, 0.6);
    color: var(--text-primary, #f0e6d3);
  }
}

.add-icon {
  color: rgba(100, 200, 100, 0.7);
  font-size: 0.8rem;
  transition: color 0.2s;
}

.rules-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  margin-top: 0.75rem;
  padding-top: 0.75rem;
  border-top: 1px solid rgba(165, 113, 58, 0.3);
}

.action-btn {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.4rem 0.8rem;
  border: 1px solid rgba(165, 113, 58, 0.5);
  border-radius: 0.25rem;
  background: rgba(165, 113, 58, 0.2);
  color: var(--text-primary, #f0e6d3);
  font-size: 0.8rem;
  cursor: pointer;
  transition: all 0.2s;

  &:hover:not(:disabled) {
    background: rgba(165, 113, 58, 0.4);
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}

.save-btn {
  &:hover:not(:disabled) {
    background: rgba(100, 150, 255, 0.3);
    border-color: rgba(100, 150, 255, 0.5);
  }
}

.reset-btn {
  &:hover:not(:disabled) {
    background: rgba(255, 150, 100, 0.3);
    border-color: rgba(255, 150, 100, 0.5);
  }
}

.setting-section {
  margin-bottom: 0.5rem;

  details {
    transition: all 0.5s ease;
  }

  summary {
    cursor: pointer;
    padding: 0.5rem;
    background: linear-gradient(135deg, rgba(43, 29, 14, 0.6) 0%, rgba(62, 42, 20, 0.4) 100%);
    border-radius: 0.4rem;
    color: var(--user-color-primary, #d4b16a);
    font-family: var(--font-title, 'ZCOOL XiaoWei', serif);
    font-size: 0.9rem;
    letter-spacing: 1px;
    transition: all 0.5s ease;
    list-style: none;
    display: flex;
    align-items: center;
    gap: 0.5rem;

    &::-webkit-details-marker {
      display: none;
    }

    &::before {
      content: '▶';
      font-size: 0.7rem;
      transition: transform 0.5s ease;
      color: var(--user-color-primary, #d4b16a);
    }

    &:hover {
      background: linear-gradient(135deg, rgba(43, 29, 14, 0.8) 0%, rgba(62, 42, 20, 0.6) 100%);
    }
  }

  &[open] summary::before {
    transform: rotate(90deg);
  }

  &[open] > summary {
    border-radius: 0.4rem 0.4rem 0 0;
    border-bottom: 1px solid rgba(165, 113, 58, 0.3);
  }

  .setting-content {
    padding: 0.75rem;
    background: rgba(43, 29, 14, 0.4);
    border-radius: 0 0 0.4rem 0.4rem;
    opacity: 0;
    transform: translateY(-10px);
    transition:
      opacity 0.5s ease,
      transform 0.5s ease;
  }
}

.setting-section[open] .setting-content {
  opacity: 1;
  transform: translateY(0);
}
