.rules-list{display:flex;flex-direction:column;gap:.5rem}.rule-item{display:flex;align-items:flex-start;gap:.5rem;background:rgba(43,29,14,.2);border:1px solid rgba(165,113,58,.2);border-radius:.4rem;padding:.5rem}.rule-input{flex:1;background:rgba(0,0,0,.3);border:1px solid rgba(165,113,58,.3);border-radius:.25rem;padding:.4rem;font-size:.8rem;color:var(--text-primary, #f0e6d3);font-family:inherit;resize:vertical;min-height:2.5rem}.rule-input:focus{outline:none;border-color:rgba(212,177,106,.8)}.rule-input::placeholder{color:rgba(184,169,143,.5)}.delete-icon{color:rgba(255,100,100,.7);cursor:pointer;margin-top:.3rem;font-size:.8rem;transition:color .2s}.delete-icon:hover{color:#ff5050}.add-rule-btn{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.5rem;border:1px dashed rgba(165,113,58,.4);border-radius:.4rem;background:rgba(43,29,14,.1);color:var(--text-secondary, #b8a98f);font-size:.8rem;cursor:pointer;transition:all .2s}.add-rule-btn:hover{background:rgba(43,29,14,.3);border-color:rgba(165,113,58,.6);color:var(--text-primary, #f0e6d3)}.add-icon{color:rgba(100,200,100,.7);font-size:.8rem;transition:color .2s}.rules-actions{display:flex;justify-content:flex-end;gap:.5rem;margin-top:.75rem;padding-top:.75rem;border-top:1px solid rgba(165,113,58,.3)}.action-btn{display:flex;align-items:center;gap:.3rem;padding:.4rem .8rem;border:1px solid rgba(165,113,58,.5);border-radius:.25rem;background:rgba(165,113,58,.2);color:var(--text-primary, #f0e6d3);font-size:.8rem;cursor:pointer;transition:all .2s}.action-btn:hover:not(:disabled){background:rgba(165,113,58,.4)}.action-btn:disabled{opacity:.5;cursor:not-allowed}.save-btn:hover:not(:disabled){background:rgba(100,150,255,.3);border-color:rgba(100,150,255,.5)}.reset-btn:hover:not(:disabled){background:rgba(255,150,100,.3);border-color:rgba(255,150,100,.5)}.setting-section{margin-bottom:.5rem}.setting-section details{transition:all .5s ease}.setting-section summary{cursor:pointer;padding:.5rem;background:linear-gradient(135deg, rgba(43, 29, 14, 0.6) 0%, rgba(62, 42, 20, 0.4) 100%);border-radius:.4rem;color:var(--user-color-primary, #d4b16a);font-family:var(--font-title, "ZCOOL XiaoWei", serif);font-size:.9rem;letter-spacing:1px;transition:all .5s ease;list-style:none;display:flex;align-items:center;gap:.5rem}.setting-section summary::-webkit-details-marker{display:none}.setting-section summary::before{content:"▶";font-size:.7rem;transition:transform .5s ease;color:var(--user-color-primary, #d4b16a)}.setting-section summary:hover{background:linear-gradient(135deg, rgba(43, 29, 14, 0.8) 0%, rgba(62, 42, 20, 0.6) 100%)}.setting-section[open] summary::before{transform:rotate(90deg)}.setting-section[open]>summary{border-radius:.4rem .4rem 0 0;border-bottom:1px solid rgba(165,113,58,.3)}.setting-section .setting-content{padding:.75rem;background:rgba(43,29,14,.4);border-radius:0 0 .4rem .4rem;opacity:0;transform:translateY(-10px);transition:opacity .5s ease,transform .5s ease}.setting-section[open] .setting-content{opacity:1;transform:translateY(0)}