
.character-detail-modal {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.7);
  z-index: 1000;
  align-items: center;
  justify-content: center;
  animation: fadeIn 0.3s ease-out;
}

.character-detail-modal.active {
  display: flex;
}

.character-detail-content {
  background: linear-gradient(135deg, rgba(43, 29, 14, 0.98) 0%, rgba(62, 42, 20, 0.95) 100%);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  width: 90%;
  max-height: 80vh;
  overflow-y: auto;
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.5),
    inset 0 1px 0 rgba(212, 177, 106, 0.1);
  animation: slideIn 0.3s ease-out;
}

.character-detail-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
  background: linear-gradient(90deg, rgba(212, 177, 106, 0.1) 0%, transparent 100%);
}

.character-name {
  font-family: var(--font-title);
  font-size: 1.1rem;
  color: var(--text-title);
  letter-spacing: 2px;
}

.character-detail-close {
  width: 1.5rem;
  height: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--text-secondary);
  font-size: 1rem;
  border-radius: 0.25rem;
  transition: all 0.2s ease;

  &:hover {
    background-color: rgba(255, 107, 107, 0.2);
    color: #ff6b6b;
  }
}

.character-detail-body {
  padding: 1rem;
}

.character-detail-info {
  margin-bottom: 1rem;
}

.female-only.hidden {
  display: none;
}
