
.character-detail-body {
  padding: 0.5rem;
}

.character-info-section {
  background: linear-gradient(135deg, rgba(43, 29, 14, 0.6) 0%, rgba(62, 42, 20, 0.4) 100%);
  border-radius: 0.5rem;
  padding: 0.75rem;
  margin-bottom: 0.5rem;
  border-left: 3px solid var(--accent-color);
}

.info-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.info-item {
  display: flex;
  flex-direction: column;
  min-width: 30%;
  flex: 1;
}

.info-label {
  font-family: var(--font-title);
  font-size: 0.75rem;
  color: var(--text-secondary);
  margin-bottom: 0.25rem;
  letter-spacing: 1px;
}

.info-value {
  font-family: var(--font-serif);
  font-size: 0.85rem;
  color: var(--text-primary);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

.status-section {
  background: linear-gradient(135deg, rgba(43, 29, 14, 0.6) 0%, rgba(62, 42, 20, 0.4) 100%);
  border-radius: 0.5rem;
  padding: 0.75rem;
}

.section-header {
  font-family: var(--font-title);
  font-size: 0.9rem;
  color: var(--text-title);
  margin-bottom: 0.75rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--border-color);
  letter-spacing: 2px;
}

.status-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.5rem;
}

.status-item {
  display: flex;
  flex-direction: column;
}

.status-label {
  font-family: var(--font-title);
  font-size: 0.7rem;
  color: var(--text-secondary);
  margin-bottom: 0.2rem;
  letter-spacing: 1px;
}

.status-value {
  font-family: var(--font-serif);
  font-size: 0.8rem;
  color: var(--text-primary);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
  line-height: 1.4;
}

.character-inventory-section {
  border-top: 1px solid var(--border-color);
  padding-top: 0.75rem;
  margin-top: 0.5rem;
}

.section-title {
  font-family: var(--font-title);
  font-size: 0.9rem;
  color: var(--text-title);
  margin-bottom: 0.5rem;
  padding-bottom: 0.25rem;
  border-bottom: 1px solid rgba(212, 177, 106, 0.2);
  letter-spacing: 1px;
}

.martial-arts-container {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.martial-art-item {
  background: linear-gradient(135deg, rgba(62, 42, 20, 0.6) 0%, rgba(43, 29, 14, 0.8) 100%);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  padding: 0.5rem 0.75rem;
  transition: all 0.3s ease;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2);

  &:hover {
    background: linear-gradient(135deg, rgba(72, 49, 23, 0.7) 0%, rgba(50, 34, 16, 0.85) 100%);
    border-color: var(--user-color-primary);
    transform: translateX(2px);
  }
}

.martial-art-name {
  font-family: var(--font-serif);
  font-size: 0.85rem;
  color: var(--text-primary);
  line-height: 1.4;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

.no-items {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  color: var(--text-secondary);
  font-family: var(--font-serif);
  font-size: 0.8rem;
  font-style: italic;
}
